SELECT     TRUNC(SYSDATE)                                  AS \"Report Date\",     im.DEPT                                         AS \"Dept No\",     d.DEPT_NAME                                     AS \"Dept Name\",     im.CLASS                                        AS \"Class No\",     c.CLASS_NAME                                    AS \"Class Name\",     im.SUBCLASS                                     AS \"Subclass No\",     sc.SUB_NAME                                     AS \"Subclass Name\",     im.ITEM                                         AS \"Item ID\",     im.ITEM_DESC                                    AS \"Item Description\",     im.STANDARD_UOM                                 AS \"UOM\",     im.PACK_IND                                     AS \"Pack IND\",     im.STATUS                                       AS \"Item Status\",     isc.SUPPLIER                                    AS \"Supplier ID\",     sp.SUP_NAME                                     AS \"Supplier Name\",     sp.SUP_STATUS                                   AS \"Supplier Status\",     isc.PRIMARY_SUPP_IND                            AS \"Primary Supp IND\",     isc.PRIMARY_COUNTRY_IND                         AS \"Primary Country IND\",     iscl.LOC                                        AS \"Location ID\",     il.LOC_TYPE                                     AS \"LOC Type\",     CASE il.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'     END                                                   AS \"LOC Type DESC\",     CASE il.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                    AS location_name,     il.STATUS                                            AS \"Item LOC Status\",      ril.REPL_METHOD                                       AS \"Repl Method\",     CASE ril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'F'  THEN 'Floating Point'         WHEN 'M'  THEN 'Min/Max'         WHEN 'T'  THEN 'Time Supply'         WHEN 'SO' THEN 'Store Orders'         ELSE ril.REPL_METHOD     END                                                   AS \"Repl Method DESC\",     ril.STOCK_CAT                                          AS \"Stock Category\",     CASE ril.STOCK_CAT         WHEN 'C' THEN 'Cross-Docked'         WHEN 'D' THEN 'Direct to Store'         WHEN 'L' THEN 'WH/Cross Link'         WHEN 'W' THEN 'Warehouse Stocked'         WHEN 'X' THEN 'PO Cross-link'     END                                                   AS \"Stock Category DESC\",      isc.UNIT_COST                                         AS \"ISC Unit Cost\",     iscl.UNIT_COST                                        AS \"ISCL Unit Cost\",     ROUND(NVL(iscl.UNIT_COST, 0) - NVL(isc.UNIT_COST, 0), 4)                                                          AS \"Unit Cost Variance\",     CASE         WHEN NVL(iscl.UNIT_COST, -1) != NVL(isc.UNIT_COST, -1)         THEN 'DIFFER'         ELSE 'MATCH'     END                                                   AS \"Unit Cost Status\",      isc.PICKUP_LEAD_TIME                                  AS \"ISC Pickup Lead Time\",     iscl.PICKUP_LEAD_TIME                                 AS \"ISCL Pickup Lead Time\",     NVL(iscl.PICKUP_LEAD_TIME, 0) - NVL(isc.PICKUP_LEAD_TIME, 0)                                                           AS pickup_lt_variance,     CASE         WHEN NVL(iscl.PICKUP_LEAD_TIME, -1) != NVL(isc.PICKUP_LEAD_TIME, -1)         THEN 'DIFFER'         ELSE 'MATCH'     END                                                   AS pickup_lt_status,      isc.ORIGIN_COUNTRY_ID                                 AS isc_origin_country,     iscl.ORIGIN_COUNTRY_ID                                AS iscl_origin_country,     CASE         WHEN NVL(iscl.ORIGIN_COUNTRY_ID, 'X') != NVL(isc.ORIGIN_COUNTRY_ID, 'X')         THEN 'DIFFER'         ELSE 'MATCH'     END                                                   AS origin_country_status,      isc.SUPP_PACK_SIZE                                    AS isc_supp_pack_size,     isc.INNER_PACK_SIZE                                   AS isc_inner_pack_size,     isc.LEAD_TIME                                         AS isc_lead_time,     isc.TI                                                AS isc_ti,     isc.HI                                                AS isc_hi,      NVL(iscl.UNIT_COST,        isc.UNIT_COST)             AS effective_unit_cost,     NVL(iscl.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME)      AS effective_pickup_lt,     NVL(iscl.ORIGIN_COUNTRY_ID,isc.ORIGIN_COUNTRY_ID)    AS effective_origin_country,      isc.LEAD_TIME                                         AS effective_lead_time,     isc.SUPP_PACK_SIZE                                    AS effective_supp_pack_size,     isc.TI                                                AS effective_ti,     isc.HI                                                AS effective_hi,      NVL(isc.TI, 0) * NVL(isc.HI, 0)         * NVL(isc.SUPP_PACK_SIZE, 1)                      AS isc_pallet_multiple,      (CASE WHEN NVL(iscl.UNIT_COST,-1)          != NVL(isc.UNIT_COST,-1)           THEN 1 ELSE 0 END      + CASE WHEN NVL(iscl.PICKUP_LEAD_TIME,-1) != NVL(isc.PICKUP_LEAD_TIME,-1)              THEN 1 ELSE 0 END      + CASE WHEN NVL(iscl.ORIGIN_COUNTRY_ID,'X') != NVL(isc.ORIGIN_COUNTRY_ID,'X')              THEN 1 ELSE 0 END     )                                                     AS total_diff_count,      CASE         WHEN NVL(iscl.UNIT_COST,-1) != NVL(isc.UNIT_COST,-1)              AND NVL(iscl.PICKUP_LEAD_TIME,-1) != NVL(isc.PICKUP_LEAD_TIME,-1)         THEN 'COST AND LEAD TIME - HIGH IMPACT'         WHEN NVL(iscl.UNIT_COST,-1) != NVL(isc.UNIT_COST,-1)         THEN 'COST ONLY - FINANCIAL IMPACT'         WHEN NVL(iscl.PICKUP_LEAD_TIME,-1) != NVL(isc.PICKUP_LEAD_TIME,-1)         THEN 'PICKUP LEAD TIME - ROQ TIMING IMPACT'         WHEN NVL(iscl.ORIGIN_COUNTRY_ID,'X') != NVL(isc.ORIGIN_COUNTRY_ID,'X')         THEN 'ORIGIN COUNTRY - IMPORT COST IMPACT'         ELSE 'OTHER PARAMETER DIFFERENCE'     END                                                   AS impact_classification,      CASE         WHEN NVL(iscl.UNIT_COST,-1) != NVL(isc.UNIT_COST,-1)         THEN 'Verify if location cost is intentional; if not, remove ISCL cost override'         WHEN NVL(iscl.PICKUP_LEAD_TIME,-1) != NVL(isc.PICKUP_LEAD_TIME,-1)         THEN 'Verify if location pickup LT reflects actual supplier performance; update if stale'         WHEN NVL(iscl.ORIGIN_COUNTRY_ID,'X') != NVL(isc.ORIGIN_COUNTRY_ID,'X')         THEN 'Verify origin country with trade compliance; update or remove ISCL override'         ELSE 'Review ISCL override values against ISC baseline and correct where stale'     END                                                   AS recommended_action,      iscl.CREATE_DATETIME                                  AS iscl_create_datetime,     iscl.LAST_UPDATE_DATETIME                             AS iscl_last_update,      ils.STOCK_ON_HAND                                     AS current_soh,     ils.AV_COST                                           AS weighted_avg_cost  FROM     MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY_LOC      iscl      JOIN  MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY    isc   ON  iscl.ITEM         = isc.ITEM                                                       AND iscl.SUPPLIER     = isc.SUPPLIER                                                       AND isc.PRIMARY_SUPP_IND    = 'Y'                                                       AND isc.PRIMARY_COUNTRY_IND = 'Y'      JOIN  MFCS_RDS.RDS_WV_REPL_ITEM_LOC        ril   ON  iscl.ITEM         = ril.ITEM                                                       AND iscl.LOC          = ril.LOCATION                                                       AND iscl.SUPPLIER     = ril.PRIMARY_REPL_SUPPLIER                                                       AND ril.REPL_METHOD  IS NOT NULL      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC              il   ON  ril.ITEM          = il.ITEM                                                       AND ril.LOCATION      = il.LOC                                                       AND ril.LOC_TYPE      = il.LOC_TYPE      JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER           im   ON  iscl.ITEM         = im.ITEM                                                       AND im.TRAN_LEVEL     = im.ITEM_LEVEL     JOIN  MFCS_RDS.RDS_WV_DEPS                  d    ON  im.DEPT           = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS                 c    ON  im.DEPT           = c.DEPT                                                       AND im.CLASS          = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS              sc   ON  im.DEPT           = sc.DEPT                                                       AND im.CLASS          = sc.CLASS                                                       AND im.SUBCLASS       = sc.SUBCLASS      LEFT JOIN MFCS_RDS.RDS_WV_STORE             st   ON  iscl.LOC          = st.STORE                                                       AND il.LOC_TYPE       = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH               wh    ON  iscl.LOC          = wh.WH                                                       AND il.LOC_TYPE       = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_SUPS              sp   ON  iscl.SUPPLIER     = sp.SUPPLIER      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH     ils   ON  iscl.ITEM         = ils.ITEM                                                       AND iscl.LOC          = ils.LOC                                                       AND ils.LOC_TYPE      = il.LOC_TYPE  WHERE     ril.REPL_METHOD  IS NOT NULL     AND il.STATUS    IN ('A','C')     AND im.STATUS     = 'A'     AND (         NVL(iscl.UNIT_COST,-1)          != NVL(isc.UNIT_COST,-1)         OR NVL(iscl.PICKUP_LEAD_TIME,-1) != NVL(isc.PICKUP_LEAD_TIME,-1)         OR NVL(iscl.ORIGIN_COUNTRY_ID,'X') != NVL(isc.ORIGIN_COUNTRY_ID,'X')     )  ORDER BY     (CASE WHEN NVL(iscl.UNIT_COST,-1) != NVL(isc.UNIT_COST,-1)      